async () => {
 const country = '{{country|js}}';
 if (!/^[a-z]{2}$/i.test(country)) throw new Error('country 必须是两位地区代码');
 const params = new URLSearchParams({term: '{{query|js}}', entity: 'software', country, limit: '20'});
 const response = await fetch('https://itunes.apple.com/search?' + params, {credentials: 'omit', signal: AbortSignal.timeout(20000)});
 if (!response.ok) throw new Error('Apple 搜索返回 HTTP ' + response.status);
 const data = await response.json();
 if (!Array.isArray(data.results)) throw new Error('Apple 搜索响应格式发生变化');
 return {country, results: data.results.map(app => ({id: String(app.trackId), name: app.trackName, developer: app.artistName, rating: app.averageUserRating, ratingCount: app.userRatingCount, price: app.price, currency: app.currency, version: app.version, updatedAt: app.currentVersionReleaseDate, url: app.trackViewUrl}))};
}
